/** Client types for contributions (Phase E). Expected outputs are always generated by the server's compiler run. */
export interface CaseResult {
  input: string;
  hidden: boolean;
  output?: string;
  error?: string;
}

export interface DraftCheck {
  fingerprint: string;
  at: string;
  ok: boolean;
  cases: CaseResult[];
}

export interface ProblemPayload {
  title: string;
  difficulty: string;
  category: string;
  description: string;
  tags: string[];
  starterCode: string;
  solution: string;
  cases: { input: string; hidden: boolean }[];
  hints: string[];
}

export interface QuestionPayload {
  section: string;
  prompt: string;
  options: string[];
  answer: number;
  explanation: string;
}

export interface ApplicationPayload {
  experience: string;
  link?: string;
}

export interface Contribution {
  id: string;
  kind: "problem" | "question" | "application";
  authorId: string;
  status: "draft" | "submitted" | "approved" | "rejected";
  payload: ProblemPayload | QuestionPayload | ApplicationPayload;
  check: DraftCheck | null;
  reviewNote: string;
  publishedRef: string;
  createdAt: string;
  updatedAt: string;
}

export function contributionTitle(c: Contribution): string {
  const p = c.payload as Partial<ProblemPayload & QuestionPayload>;
  return p.title ?? p.prompt ?? "Contributor application";
}

export const STATUS_STYLE: Record<Contribution["status"], string> = {
  draft: "bg-muted text-muted-foreground",
  submitted: "bg-blue-500/10 text-blue-600 dark:text-blue-400",
  approved: "bg-green-500/10 text-green-600 dark:text-green-400",
  rejected: "bg-red-500/10 text-red-600 dark:text-red-400",
};
